import type { Attachment } from '../domain/index.ts';

/**
 * Binary storage for evidence files (docs/adr/0002 object-storage adapter). Keys are opaque
 * and generated by the service; adapters never derive paths from user input.
 */
export type ObjectStorage = {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  /** null when the object no longer exists. */
  get(key: string): Promise<Uint8Array | null>;
  /** Idempotent: deleting a missing object succeeds. */
  delete(key: string): Promise<void>;
};

export type AttachInput = Omit<Attachment, 'projectId' | 'projectName'> & {
  /** Stored module name of the linked record (e.g. `Eventos`). */
  readonly recordModule: string;
  readonly scopeProjectId: string;
};

export type AttachmentQuery = {
  readonly linkedModule: string | null;
  readonly linkedRecordId: string | null;
  readonly q: string | null;
  readonly limit: number;
};

/** Metadata persistence; every call runs in one tenant transaction (docs/adr/0003). */
export type AttachmentStore = {
  /**
   * Inserts the metadata, appends the link to the record payload and audits it atomically.
   * Returns null when the linked record does not exist (nothing is written).
   */
  attach(tenantId: string, input: AttachInput): Promise<Attachment | null>;
  list(tenantId: string, query: AttachmentQuery): Promise<Attachment[]>;
  get(tenantId: string, id: string): Promise<Attachment | null>;
};

export type Clock = { now(): Date };
export type RandomHex = (length: number) => string;

/**
 * Plain text of an untrusted document, for the in-app viewer. Implementations throw on
 * unreadable input; the service reports that without parser details.
 */
export type TextExtractor = {
  /** Page texts, or null when the PDF has more than `maxPages` pages. */
  pdf(bytes: Uint8Array, maxPages: number): Promise<readonly string[] | null>;
  /** Paragraphs, then table rows as tab-separated lines. */
  docx(bytes: Uint8Array): Promise<readonly string[]>;
};
